const fs = require('fs');
const { execSync } = require('child_process');

const raw = execSync('npx --yes markdownlint-cli2 "**/*.md"', {
  cwd: process.argv[2],
  encoding: 'utf8',
  maxBuffer: 64 * 1024 * 1024,
  stdio: ['ignore', 'pipe', 'pipe'],
});
process.exit(0);

cwd = process.argv[2];
let out = '';
try {
  out = execSync('npx --yes markdownlint-cli2 "**/*.md"', { cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
} catch (e) {
  out = (e.stdout || '') + (e.stderr || '');
}

const rows = out.split(/\r?\n/).filter(l => l.includes('error MD013'));
const cls = { table: 0, fence: 0, link: 0, prose: 0 };
const lens = [];
const files = {};
const samples = [];
const fenceRanges = new Map();

function inFence(file, lineNo) {
  if (!fenceRanges.has(file)) {
    const ranges = [];
    let open = null;
    fs.readFileSync(file, 'utf8').split(/\r?\n/).forEach((l, i) => {
      if (/^\s*```/.test(l)) {
        if (open === null) open = i + 1; else { ranges.push([open, i + 1]); open = null; }
      }
    });
    fenceRanges.set(file, ranges);
  }
  return fenceRanges.get(file).some(([a, b]) => lineNo >= a && lineNo <= b);
}

for (const row of rows) {
  const m = row.match(/^(.*?):(\d+):(\d+)/);
  if (!m) continue;
  const file = m[1];
  const lineNo = Number(m[2]);
  let text = '';
  try { text = fs.readFileSync(file, 'utf8').split(/\r?\n/)[lineNo - 1] || ''; } catch (e) { continue; }
  files[file] = (files[file] || 0) + 1;
  lens.push(text.length);
  if (/^\s*\|/.test(text)) cls.table++;
  else if (inFence(file, lineNo)) cls.fence++;
  else if (/\]\(/.test(text)) cls.link++;
  else { cls.prose++; if (samples.length < 8) samples.push(file + ':' + lineNo + ' len=' + text.length); }
}

lens.sort((a, b) => a - b);
console.log('MD013 total: ' + rows.length);
console.log('composition: ' + JSON.stringify(cls));
console.log('len min/median/max: ' + lens[0] + ' / ' + lens[Math.floor(lens.length / 2)] + ' / ' + lens[lens.length - 1]);
console.log('files:');
Object.entries(files).sort((a, b) => b[1] - a[1]).forEach(([f, c]) => console.log('  ' + String(c).padStart(3) + '  ' + f));
console.log('prose samples:');
samples.forEach(s => console.log('  ' + s));

